class AuthRepository {

    private val auth: FirebaseAuth = FirebaseAuth.getInstance()

    val currentUser: FirebaseUser?
        get() = auth.currentUser

    suspend fun registrar(email: String, password: String): Result<Unit> = try {
        val result = auth.createUserWithEmailAndPassword(email, password).await()
        result.user?.sendEmailVerification()?.await()
        auth.signOut()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun iniciarSesion(email: String, password: String): Result<FirebaseUser> = try {
        val result = auth.signInWithEmailAndPassword(email, password).await()
        val user = result.user ?: throw IllegalStateException("Usuario no encontrado")
        if (!user.isEmailVerified && !AdminConfig.sinVerificacion(user.email)) {
            try {
                user.sendEmailVerification().await()
            } catch (e: Exception) {
            }
            auth.signOut()
            throw IllegalStateException("Debes verificar tu correo para entrar. Te reenviamos el mensaje de verificación.")
        }
        val perfil = FirebaseFirestore.getInstance().collection("consultoras").document(user.uid).get().await()
            .toObject(ConsultoraProfile::class.java)
        if (perfil != null && !perfil.activo) {
            auth.signOut()
            throw IllegalStateException("Tu cuenta fue dada de baja. Comunícate con la administración.")
        }
        Result.success(user)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun enviarCorreoRecuperacion(email: String): Result<Unit> = try {
        auth.sendPasswordResetEmail(email).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    fun sesionValida(): Boolean {
        val user = auth.currentUser ?: return false
        if (user.isEmailVerified || AdminConfig.sinVerificacion(user.email)) return true
        auth.signOut()
        return false
    }

    fun cerrarSesion() {
        auth.signOut()
    }
}

class ProfileRepository {

    private val db = FirebaseFirestore.getInstance()
    private val coleccion = db.collection("consultoras")
    private fun documento(uid: String) = coleccion.document(uid)

    suspend fun guardarPerfil(perfil: ConsultoraProfile): Result<Unit> = try {
        val datos = mapOf(
            "uid" to perfil.uid,
            "nombre" to perfil.nombre,
            "email" to perfil.email,
            "preferencias" to perfil.preferencias,
            "fotoBase64" to perfil.fotoBase64,
            "activo" to perfil.activo,
            "rol" to perfil.rol,
            "ultimaActualizacion" to perfil.ultimaActualizacion,
            "nivel" to perfil.nivel,
            "progreso" to perfil.progreso,
            "dni" to perfil.dni,
            "celular" to perfil.celular,
            "direccionEntrega" to perfil.direccionEntrega,
            "distrito" to perfil.distrito,
            "referencia" to perfil.referencia,
            "tipoComprobante" to perfil.tipoComprobante,
            "esAdmin" to FieldValue.delete() // Eliminamos el campo obsoleto
        )
        documento(perfil.uid).set(datos).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun obtenerPerfil(uid: String): Result<ConsultoraProfile?> = try {
        val snapshot = documento(uid).get().await()
        val perfil = snapshot.toObject(ConsultoraProfile::class.java)

        // Lógica de migración: esAdmin (Boolean) -> rol (String)
        val rolFinal = when {
            perfil?.rol != null && perfil.rol != "CONSULTORA" -> perfil.rol
            perfil?.esAdmin == true -> "DIRECTORA_COMERCIAL"
            else -> "CONSULTORA"
        }

        val perfilMigrado = perfil?.copy(rol = rolFinal)
        Result.success(perfilMigrado)
    } catch (e: Exception) {
        Result.failure(e)
    }

    fun observarConsultoras(): Flow<List<ConsultoraProfile>> = callbackFlow {
        val registro = coleccion.addSnapshotListener { snapshot, error ->
            if (error != null) {
                close(error)
                return@addSnapshotListener
            }
            val consultoras = snapshot?.documents?.mapNotNull { doc ->
                doc.toObject(ConsultoraProfile::class.java)
            } ?: emptyList()
            trySend(consultoras)
        }
        awaitClose { registro.remove() }
    }

    suspend fun actualizarProgreso(uid: String, nivel: String, progreso: Double): Result<Unit> = try {
        documento(uid).update(mapOf("nivel" to nivel, "progreso" to progreso)).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun actualizarDatosAdmin(
        uid: String,
        nombre: String,
        dni: String,
        celular: String,
        preferencias: String,
        direccionEntrega: String,
        distrito: String,
        referencia: String
    ): Result<Unit> = try {
        documento(uid).update(
            mapOf(
                "nombre" to nombre,
                "dni" to dni,
                "celular" to celular,
                "preferencias" to preferencias,
                "direccionEntrega" to direccionEntrega,
                "distrito" to distrito,
                "referencia" to referencia,
                "ultimaActualizacion" to System.currentTimeMillis()
            )
        ).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun actualizarEstado(uid: String, activo: Boolean): Result<Unit> = try {
        documento(uid).update(mapOf("activo" to activo)).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun asignarRol(correo: String, nuevoRol: String, asignadoPor: String): Result<Unit> = try {
        val uid = obtenerUidPorCorreo(correo) ?: throw IllegalStateException("Usuario no encontrado")
        documento(uid).update(
            mapOf(
                "rol" to nuevoRol,
                "ultimaActualizacion" to System.currentTimeMillis(),
                "asignadoPor" to asignadoPor
            )
        ).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    private suspend fun obtenerUidPorCorreo(correo: String): String? = try {
        val query = coleccion.whereEqualTo("email", correo).get().await()
        query.documents.firstOrNull()?.id
    } catch (e: Exception) {
        null
    }
}

class ProductRepository {

    private val coleccion = FirebaseFirestore.getInstance().collection("productos")

    fun observarCatalogo(): Flow<List<Producto>> = catalogoCompartido.map { it.getOrThrow() }

    suspend fun sembrarProductosDeEjemplo() {
        val ejemplos = listOf(
            Producto(nombre = "Labial Mate Rosa", categoria = "Maquillaje", precio = 29.9, descripcion = "Larga duración", stock = 40, imagenUrl = IMG_LABIAL),
            Producto(nombre = "Base Líquida Natural", categoria = "Maquillaje", precio = 45.5, descripcion = "Cobertura media", stock = 25, imagenUrl = IMG_BASE),
            Producto(nombre = "Crema Facial Hidratante", categoria = "Tratamiento facial", precio = 38.0, descripcion = "Con ácido hialurónico", stock = 30, imagenUrl = IMG_CREMA),
            Producto(nombre = "Sérum Antiedad", categoria = "Tratamiento facial", precio = 65.0, descripcion = "Con vitamina C", stock = 15, imagenUrl = IMG_SERUM),
            Producto(nombre = "Perfume Floral 50ml", categoria = "Fragancias", precio = 89.9, descripcion = "Notas florales", stock = 20, imagenUrl = IMG_PERFUME),
            Producto(nombre = "Vela Aromática Vainilla", categoria = "Velas", precio = 24.9, descripcion = "40 horas de duración", stock = 35, imagenUrl = IMG_VELA)
        )
        try {
            ejemplos.forEach { producto ->
                val doc = coleccion.document()
                doc.set(producto.copy(id = doc.id)).await()
            }
        } catch (e: Exception) {
        }
    }

    suspend fun agregarProducto(producto: Producto): Result<Unit> = try {
        val doc = coleccion.document()
        doc.set(producto.copy(id = doc.id)).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun actualizarProducto(
        id: String,
        nombre: String,
        categoria: String,
        precio: Double,
        descripcion: String,
        stock: Int,
        comision: Double
    ): Result<Unit> = try {
        coleccion.document(id).update(
            mapOf(
                "nombre" to nombre,
                "categoria" to categoria,
                "precio" to precio,
                "descripcion" to descripcion,
                "stock" to stock,
                "comision" to comision
            )
        ).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun eliminarProducto(id: String): Result<Unit> = try {
        coleccion.document(id).delete().await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun actualizarStockPorDevolucion(productoId: String, apto: Boolean) {
        if (apto) {
            coleccion.document(productoId).update("stock", FieldValue.increment(1)).await()
        }
    }

    suspend fun descontarStockPorVenta(productoId: String, cantidadVendida: Int): Result<Unit> = try {
        coleccion.document(productoId).update("stock", FieldValue.increment(-cantidadVendida.toLong())).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    companion object {
        private val ambito = CoroutineScope(SupervisorJob() + Dispatchers.Default)

        private val catalogoCompartido: Flow<Result<List<Producto>>> = callbackFlow<Result<QuerySnapshot>> {
            val registro = FirebaseFirestore.getInstance().collection("productos")
                .addSnapshotListener { snapshot, error ->
                    if (error != null) {
                        trySend(Result.failure(error))
                    } else if (snapshot != null) {
                        trySend(Result.success(snapshot))
                    }
                }
            awaitClose { registro.remove() }
        }
            .map { resultado ->
                resultado.mapCatching { snapshot ->
                    snapshot.documents.mapNotNull { doc ->
                        doc.toObject(Producto::class.java)?.copy(id = doc.id)
                    }
                }
            }
            .flowOn(Dispatchers.Default)
            .shareIn(ambito, SharingStarted.WhileSubscribed(5_000L), replay = 1)

        private const val IMG_LABIAL = ""
        private const val IMG_BASE = ""
        private const val IMG_CREMA = ""
        private const val IMG_SERUM = ""
        private const val IMG_PERFUME = ""
        private const val IMG_VELA = ""
    }
}

class CapacitacionRepository {

    private val db = FirebaseFirestore.getInstance()
    private val coleccionCapacitaciones = db.collection("capacitaciones")
    private val coleccionProgreso = db.collection("progreso_capacitaciones")

    fun observarCapacitaciones(): Flow<List<Capacitacion>> = callbackFlow {
        val registro = coleccionCapacitaciones.addSnapshotListener { snapshot, error ->
            if (error != null) {
                close(error)
                return@addSnapshotListener
            }
            val capacitaciones = snapshot?.documents?.mapNotNull { doc ->
                doc.toObject(Capacitacion::class.java)?.copy(id = doc.id)
            } ?: emptyList()
            trySend(capacitaciones)
        }
        awaitClose { registro.remove() }
    }

    suspend fun crearCapacitacion(capacitacion: Capacitacion): Result<Unit> = try {
        val doc = coleccionCapacitaciones.document()
        doc.set(capacitacion.copy(id = doc.id)).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    suspend fun guardarProgreso(progreso: ProgresoCapacitacion): Result<Unit> = try {
        coleccionProgreso.document().set(progreso).await()
        Result.success(Unit)
    } catch (e: Exception) {
        Result.failure(e)
    }

    fun observarProgresoDe(uid: String): Flow<List<ProgresoCapacitacion>> = callbackFlow {
        val registro = coleccionProgreso.whereEqualTo("uid", uid).addSnapshotListener { snapshot, error ->
            if (error != null) {
                close(error)
                return@addSnapshotListener
            }
            val progresos = snapshot?.documents?.mapNotNull { doc ->
                doc.toObject(ProgresoCapacitacion::class.java)
            } ?: emptyList()
            trySend(progresos)
        }
        awaitClose { registro.remove() }
    }
}
